//! Option selection (seam-runtime 0.90.0) against `../conformance/selection_rule_v1_vectors.json`: the
//! runtime's own fixture (`crates/seam-types/tests/fixtures/selection_rule_v1_vectors.json`, generated by
//! `scripts/selection_rule_v1_vectors.py`, an independent stdlib-only implementation of
//! `selection-rule.v1.md`), byte-identical.
//!
//! Pinned here: `codec` (the body, `selection_digest`, field 9, the `0x04` trailer and its twelve
//! refusals), every `rule_cases` entry (`decide()`), every `sealed_cases` entry (the verifier's steps 6-9)
//! and `commitment_digest_v5` (field 9 framed from the selection digest). `activation_cases`,
//! `policy_ingress_cases`, `proposal_ingress_cases` and `flag_off_golden_cases` pin the runtime's open,
//! policy and proposal gates, which a verifier never runs; they are not exercised.
//!
//! The sealed cases' signatures are 64-byte placeholders: the selection steps never verify a signature
//! (the PoP is pinned by `voter_pop_v1_payload_vector.json`, `tests/voter_vectors.rs`).
//!
//! Excluded from the published package (see `Cargo.toml`), for the reason `tests/conformance.rs` is. The
//! in-crate unit tests in `src/selection.rs` ship.

use seam_verify::commitment::{
    commitment_digest_with_explanation, explanation_digest, Commitment, ExplanationEntry,
    VoterVerification,
};
use seam_verify::selection::{
    decide, decode_body, decode_trailer, encode_body, encode_trailer, selection_digest,
    verify_selection, Decision, SelectionBlock,
};
use seam_verify::voter::ContentContext;
use serde_json::Value;

fn load() -> Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../conformance/selection_rule_v1_vectors.json");
    serde_json::from_str(
        &std::fs::read_to_string(&p)
            .unwrap_or_else(|e| panic!("{}: {e} — this test refuses to skip", p.display())),
    )
    .unwrap()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn unhex(h: &str) -> Vec<u8> {
    (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap())
        .collect()
}

fn s(v: &Value, k: &str) -> String {
    v[k].as_str()
        .unwrap_or_else(|| panic!("{k} is not a string"))
        .to_owned()
}

fn u32_(v: &Value, k: &str) -> u32 {
    u32::try_from(v[k].as_u64().unwrap()).unwrap()
}

fn strs(v: &Value, k: &str) -> Vec<String> {
    v[k].as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap().to_owned())
        .collect()
}

/// A vector `record` / `block`. A `rule_cases` record carries no winner (decide ignores it).
fn block(v: &Value) -> SelectionBlock {
    SelectionBlock {
        rule: s(v, "rule"),
        rule_version: u32_(v, "rule_version"),
        default_weight: u32_(v, "default_weight"),
        weights: v["weights"]
            .as_array()
            .unwrap()
            .iter()
            .map(|w| (s(w, "participant"), u32_(w, "weight")))
            .collect(),
        tie: s(v, "tie"),
        abstention: s(v, "abstention"),
        min_ballots: u32_(v, "min_ballots"),
        policy_version: s(v, "policy_version"),
        rules_digest: unhex(&s(v, "rules_digest")).try_into().unwrap(),
        participants: strs(v, "participants"),
        on_behalf_of: strs(v, "on_behalf_of"),
        context: v["context"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| ContentContext {
                ctx_ref: s(c, "ctx_ref"),
                content_hash: s(c, "content_hash"),
            })
            .collect(),
        winner_proposal_id: v
            .get("winner_proposal_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned(),
    }
}

fn voter(v: &Value) -> Option<VoterVerification> {
    if v.is_null() {
        return None;
    }
    // `malformed_proposal_with_voter_record` carries a partial record (decide() checks only presence),
    // so a missing field reads as its zero value here.
    let n = |k: &str| v.get(k).and_then(Value::as_u64).unwrap_or(0);
    let t = |k: &str| v.get(k).and_then(Value::as_str).unwrap_or("").to_owned();
    Some(VoterVerification {
        method: t("method"),
        principal: t("principal"),
        content_digest: unhex(&t("content_digest")),
        issued_at_ms: n("issued_at_ms"),
        expires_at_ms: n("expires_at_ms"),
        signature: unhex(&t("signature")),
        signer_certificate: unhex(&t("signer_certificate")),
        tenant: t("tenant"),
        namespace: t("namespace"),
        session_id: t("session_id"),
        opened_at_millis: n("opened_at_millis"),
        issuer: t("issuer"),
        audience: t("audience"),
        accepted_at_ms: n("accepted_at_ms"),
    })
}

fn entries(v: &Value) -> Vec<ExplanationEntry> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| ExplanationEntry {
            kind: s(e, "kind"),
            participant: s(e, "participant"),
            proposal_id: s(e, "proposal_id"),
            value: s(e, "value"),
            reason: s(e, "reason"),
            confidence: e.get("confidence").and_then(Value::as_f64),
            rationale_ref: e
                .get("rationale_ref")
                .and_then(Value::as_str)
                .map(str::to_owned),
            voter_verification: voter(e.get("voter_verification").unwrap_or(&Value::Null)),
        })
        .collect()
}

#[test]
fn codec_body_digest_field_9_and_trailer_match() {
    let v = load();
    let c = &v["codec"];
    let b = block(&c["block"]);
    let body = encode_body(&b);
    assert_eq!(hex(&body), s(c, "body"));
    assert_eq!(decode_body(&body).unwrap(), b);
    let d = selection_digest(&body);
    assert_eq!(hex(&d), s(c, "selection_digest"));
    let mut f9 = vec![1u8];
    f9.extend_from_slice(&32u64.to_be_bytes());
    f9.extend_from_slice(&d);
    assert_eq!(hex(&f9), s(c, "field_9"));
    let t = encode_trailer(&body);
    assert_eq!(hex(&t), s(c, "trailer"));
    assert_eq!(decode_trailer(&t).unwrap(), b);
}

#[test]
fn every_trailer_refusal_is_refused_by_name() {
    let v = load();
    let refusals = v["codec"]["trailer_refusals"].as_array().unwrap();
    assert_eq!(refusals.len(), 12);
    for r in refusals {
        let got = decode_trailer(&unhex(&s(r, "trailer")))
            .map(|_| ())
            .map_err(|e| e.name());
        assert_eq!(got, Err(r["reason"].as_str().unwrap()), "{}", s(r, "name"));
    }
}

fn scores_json(t: &seam_verify::selection::Tally) -> Value {
    Value::Array(
        t.scores
            .iter()
            .map(|(p, sc)| serde_json::json!({"proposal_id": p, "score": sc}))
            .collect(),
    )
}

#[test]
fn every_rule_case_decides_as_the_vector_says() {
    let v = load();
    let cases = v["rule_cases"].as_array().unwrap();
    assert_eq!(cases.len(), 30);
    for c in cases {
        let name = s(c, "name");
        let want = &c["expect"];
        let got = match decide(&block(&c["record"]), &entries(&c["entries"])) {
            Decision::Winner {
                proposal_id,
                option,
                tally,
            } => serde_json::json!({"result": "winner", "winner_proposal_id": proposal_id,
                "option": option, "scores": scores_json(&tally), "ballots": tally.ballots}),
            Decision::NoWinner { reason, tally } => serde_json::json!({"result": "no_winner",
                "reason": reason, "scores": scores_json(&tally), "ballots": tally.ballots}),
            Decision::Malformed { reason, at } => {
                serde_json::json!({"result": "malformed", "reason": reason, "at": at})
            }
        };
        assert_eq!(&got, want, "{name}");
    }
}

#[test]
fn every_sealed_case_verifies_as_the_vector_says() {
    let v = load();
    let cases = v["sealed_cases"].as_array().unwrap();
    assert_eq!(cases.len(), 13);
    for c in cases {
        let name = s(c, "name");
        let want = &c["expect"];
        let b = block(&c["block"]);
        // The block a verifier holds came off the wire: it must survive a strict re-decode.
        assert_eq!(decode_body(&encode_body(&b)).unwrap(), b, "{name}");
        let got = match verify_selection(&b, &entries(&c["entries"]), &s(c, "action")) {
            Ok(ok) => serde_json::json!({"result": "verified",
                "winner_proposal_id": ok.winner_proposal_id, "votes_linked": ok.votes_linked}),
            Err(e) => {
                let mut o = serde_json::json!({"result": e.name()});
                if let seam_verify::selection::SelectionFailure::WinnerMismatch { recomputed } = &e
                {
                    o["recomputed"] = recomputed.as_str().into();
                }
                if want.get("at").is_some() {
                    o["at"] = e.at().into();
                }
                o
            }
        };
        assert_eq!(&got, want, "{name}");
    }
}

#[test]
fn commitment_digest_v5_frames_field_9_from_the_selection_digest() {
    let v = load();
    let cd = &v["commitment_digest_v5"];
    let verified = v["sealed_cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["name"] == "verified")
        .unwrap();
    let sealed = entries(&verified["entries"]);
    let cases = cd["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 3);
    let opt = |x: &Value| x.as_str().map(unhex);
    for c in cases {
        let name = s(c, "name");
        let m = &c["commitment"];
        let expl: [u8; 32] = unhex(&s(c, "explanation_digest")).try_into().unwrap();
        if name.starts_with("populated") {
            // The populated cases' explanation is the `verified` sealed case's seven entries.
            assert_eq!(explanation_digest(&sealed).unwrap(), expl, "{name}");
        }
        let commitment = Commitment {
            id: s(m, "id"),
            action: s(m, "action"),
            authority: s(m, "authority"),
            supersedes: m["supersedes"].as_str().map(str::to_owned),
            auth_method: s(m, "auth_method"),
            trust_basis: s(m, "trust_basis"),
            committer: s(m, "committer"),
            explanation: vec![],
            selection_digest: opt(&c["selection_digest"]),
            certificate_digest: opt(&c["certificate_digest"]),
            governing_doc_sha256: opt(&c["governing_doc_sha256"]),
            signed_artifact: String::new(),
        };
        let got = commitment_digest_with_explanation(&commitment, &expl).unwrap();
        assert_eq!(hex(&got), s(c, "commitment_digest"), "{name}");
    }
    // The selection digest the populated cases frame is the codec block's.
    let body = encode_body(&block(&v["codec"]["block"]));
    assert_eq!(
        hex(&selection_digest(&body)),
        s(&cases[1], "selection_digest")
    );
}
